interface Preferences {
  displayName: string;
  email: string;
  language: string;
  weeklyDigest: boolean;
  mentions: boolean;
}

const preferences: Preferences = {
  displayName: "Maya Okafor",
  email: "maya@example.com",
  language: "en",
  mentions: false,
  weeklyDigest: true,
};

const samplePreferences: Preferences = {
  displayName: "Display name",
  email: "name@example.com",
  language: "en",
  mentions: true,
  weeklyDigest: true,
};

interface Settings {
