  device: string;
  location: string;
  lastActive: string;
  current: boolean;
}

const sessions: Session[] = [
  {
    current: true,
    device: "Safari on macOS",
    id: "1",
    lastActive: "Active now",
    location: "Berlin, Germany",
  },
  {
    current: false,
