export {
  article,
  members,
  paragraphs,
  preferences,
  profile,
  sampleArticle,
  sampleMembers,
  sampleParagraphs,
  samplePreferences,
  sampleProfile,
  sampleSessions,
  sampleSettings,
  sessions,
  settings,
};

export type { Article, Member, Preferences, Profile, Session, Settings };

import SkeletonStates from "../examples/skeleton-states";

const Example = () => <SkeletonStates />;

export default Example;
